package dev.shadw.khemet.mobs;

import dev.shadw.khemet.Chariot;
import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Chariot with its own model and texture. Generated by shadw-mod mob. */
public class ChariotRenderer extends MobRenderer<Chariot, ChariotModel.State, ChariotModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("khemet", "textures/entity/chariot.png");

	public ChariotRenderer(EntityRendererProvider.Context context) {
		super(context, new ChariotModel(context.bakeLayer(ChariotModel.LAYER)), 1.2F);
	}

	@Override
	public ChariotModel.State createRenderState() {
		return new ChariotModel.State();
	}

	@Override
	public void extractRenderState(Chariot entity, ChariotModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(ChariotModel.State state) {
		return TEXTURE;
	}
}
